/* eslint-disable @next/next/no-img-element */
// AVIF/WebP generated by scripts/images.mjs into /images/generated/, original as fallback.
// `variants` adds smaller widths to the srcset (files named <base><suffix>.avif/.webp).
export function Picture({ src, alt, width, height, priority = false, className = "", sizes, variants = [] }: {
  src: string; alt: string; width: number; height: number; priority?: boolean; className?: string; sizes?: string;
  variants?: { suffix: string; w: number }[];
}) {
  const base = src.replace(/^\/images\//, "/images/generated/").replace(/\.[^.]+$/, "");
  const set = (ext: string) => [...variants.map((v) => `${base}${v.suffix}.${ext} ${v.w}w`), `${base}.${ext} ${width}w`].join(", ");
  const s = variants.length ? sizes ?? "100vw" : sizes;
  return (
    <picture>
      <source type="image/avif" srcSet={variants.length ? set("avif") : `${base}.avif`} sizes={s} />
      <source type="image/webp" srcSet={variants.length ? set("webp") : `${base}.webp`} sizes={s} />
      <img src={src} alt={alt} width={width} height={height} className={className}
        loading={priority ? "eager" : "lazy"} fetchPriority={priority ? "high" : "auto"} decoding="async" />
    </picture>
  );
}
